export const NOTES: readonly Note[] = [
  {
    ko: "탑 노트",
    en: "Top note",
    latin: "Citrus aurantium",
    family: "top",
    plate: TOP_PLATE,
  },
  {
    ko: "하트 노트",
    en: "Heart note",
    latin: "Paeonia lactiflora",
    family: "heart",
    plate: HEART_PLATE,
  },
  {
    ko: "베이스 노트",
    en: "Base note",
    latin: "Vetiveria zizanioides",
    family: "base",
    plate: BASE_PLATE,
  },
];

/* --------------------------------------------------------------------------
   THE SIGNATURE FLOWER — the pinned "the bloom" section.
   A large eight-petal flower drawn at viewBox 0 0 600 600, centered. Each
   petal is its own <g> so useScrollProgress can drive scale+rotation per
   petal via the shared --bloom-open variable. Petals are pre-drawn (the
   line-art is static/complete here — this plate is about OPENING, not
   drawing), so every stroke has a wide d0..d1 window of 0..1 (always drawn)
   and the motion is purely the petal-group transform.
   -------------------------------------------------------------------------- */

export type Petal = {
  /** transform placing this petal around the center (rotation in deg) */
  rotate: number;
  /** petal outline `d`, authored pointing "up" from center 300,300 */
  d: string;
  /** inner highlight vein */
  vein: string;
  /** draw order on a notional clock — but here all petals are pre-drawn */
  tier: 0 | 1;
};

// A petal shape authored pointing up from (300, 300): a rounded teardrop.
const PETAL_INNER_D =
  "M300 300 C 286 270, 286 236, 300 210 C 314 236, 314 270, 300 300 Z";
const PETAL_INNER_VEIN = "M300 296 C 300 270, 300 244, 300 220";
const PETAL_OUTER_D =
  "M300 300 C 278 260, 278 214, 300 176 C 322 214, 322 260, 300 300 Z";
const PETAL_OUTER_VEIN = "M300 296 C 300 262, 300 230, 300 196";

// Inner ring of 5 petals (drawn on top, smaller), outer ring of 8 (larger).
const INNER_ROTATIONS = [0, 72, 144, 216, 288];
const OUTER_ROTATIONS = [36, 81, 126, 171, 216, 261, 306, 351];

export const SIGNATURE_PETALS: Petal[] = [
  ...INNER_ROTATIONS.map((rotate) => ({
    rotate,
    d: PETAL_INNER_D,
    vein: PETAL_INNER_VEIN,
    tier: 1 as const,
  })),
  ...OUTER_ROTATIONS.map((rotate) => ({
    rotate,
    d: PETAL_OUTER_D,
    vein: PETAL_OUTER_VEIN,
    tier: 0 as const,
  })),
];

// The center disc + anthers (always visible; they scale slightly with open)
export const SIGNATURE_CENTER = {
  // the receptacle disc
  disc: "M300 300 m -20 0 a 20 20 0 1 0 40 0 a 20 20 0 1 0 -40 0",
  // six anther dots placed around the disc
  anthers: [
    { cx: 300, cy: 286 },
    { cx: 314, cy: 292 },
    { cx: 318, cy: 308 },
    { cx: 308, cy: 318 },
    { cx: 292, cy: 318 },
    { cx: 282, cy: 308 },
  ],
};

// The blush wash that fills as the flower opens — one big disc.
export const SIGNATURE_WASH =
  "M300 300 m -150 0 a 150 150 0 1 0 300 0 a 150 150 0 1 0 -300 0";

"use client";

import type { CSSProperties } from "react";
import { HERO_PLATE } from "./botanical";
import { useLineDraw } from "../hooks/useLineDraw";
import { usePrefersReducedMotion } from "../hooks/usePrefersReducedMotion";
import { useWashSettle } from "../hooks/useWashSettle";

/**
 * The arrival. A warm-cream page where a botanical stem draws itself in as
 * you settle — stroke-dashoffset windows staggered along the plate's own
 * drawing clock — while the blush and green watercolor washes behind it
 * bloom outward (feDisplacementMap scale easing from ~60 → 0) and settle.
 * Without JavaScript, or under reduced motion, the whole illustration
 * stands complete and settled: line fully drawn, wash at rest.
 *
 * This is the medium that makes BLOOM distinct from SAKURA: SAKURA scatters
 * cherry-blossom particles across a dark/pink canvas; BLOOM draws a single
 * botanical plate, stroke by stroke, on a light cream ground, then blooms
 * watercolor behind it. Same family thesis (ink → bloom), different
 * medium, different ground.
 */
export default function Hero() {
  const reduced = usePrefersReducedMotion();
  const drawRef = useLineDraw<HTMLDivElement>(reduced);
  const washRef = useWashSettle<HTMLDivElement>(reduced);
  const p = HERO_PLATE;

  return (
    <header id="bloom-hero" className="bloom-hero">
      <div className="bloom-hero__sun" aria-hidden="true" />

      <div
        ref={drawRef}
        className="bloom-hero__stage"
        aria-hidden="true"
      >
        {/* The wash layer sits behind the line-art and blooms through a
            shared feTurbulence+feDisplacementMap filter. */}
        <div ref={washRef} className="bloom-hero__washes">
          <svg
            className="bloom-wash-svg"
            viewBox={p.viewBox}
            preserveAspectRatio="xMidYMax meet"
            aria-hidden="true"
            focusable="false"
          >
            <defs>
              <filter
                id="bloom-hero-wash"
                x="-20%"
                y="-20%"
                width="140%"
                height="140%"
              >
                <feTurbulence
                  type="fractalNoise"
                  baseFrequency="0.012 0.018"
                  numOctaves="2"
                  seed="11"
                  result="wet"
                />
                <feDisplacementMap
                  in="SourceGraphic"
                  in2="wet"
                  scale="0"
                  xChannelSelector="R"
                  yChannelSelector="G"
                />
              </filter>
            </defs>
            <g filter="url(#bloom-hero-wash)">
              {p.washes.map((w, i) => (
                <path key={i} className={w.cls} d={w.d} />
              ))}
            </g>
          </svg>
        </div>

        {/* The line-art layer — every stroke draws along the shared clock. */}
        <svg
          className="bloom-hero__lines"
          viewBox={p.viewBox}
          preserveAspectRatio="xMidYMax meet"
          aria-hidden="true"
          focusable="false"
        >
          <g className="bloom-draw">
            {p.strokes.map((s, i) => (
              <path
                key={`s${i}`}
                className={`bloom-draw__stroke ${s.cls}`}
                d={s.d}
                pathLength={1}
                strokeWidth={s.w}
                style={
                  {
                    "--d0": s.d0,
                    "--d1": s.d1,
                  } as CSSProperties
                }
              />
            ))}
            {p.leaves.map((l, i) => (
              <g key={`l${i}`} transform={l.xform}>
                <path
                  className="bloom-draw__stroke bloom-leaf-line"
                  d={l.d}
                  pathLength={1}
                  strokeWidth={2}
                  style={
                    {
                      "--d0": l.d0,
                      "--d1": l.d1 - 0.06,
                    } as CSSProperties
                  }
                />
                <path
                  className="bloom-draw__stroke bloom-vein"
                  d={l.vein}
                  pathLength={1}
                  strokeWidth={1}
                  style={
                    {
                      "--d0": l.d1 - 0.06,
                      "--d1": l.d1,
                    } as CSSProperties
                  }
                />
              </g>
            ))}
          </g>
        </svg>
      </div>

      <div className="bloom-hero__copy">
        <p className="bloom-hero__kicker">
          <span lang="ko">식물 향수 하우스</span>{" "}
          <span aria-hidden="true">·</span> BOTANICAL PERFUME
        </p>
        <h1 className="bloom-hero__title">
          <span lang="ko" className="bloom-hero__hangul">
            피다
          </span>
          <span className="bloom-hero__latin">
            BLOOM
            <span className="bloom-hero__latin-sub">
              a perfume that opens
            </span>
          </span>
        </h1>
        <p className="bloom-hero__lede">
          <em>A scent is not a thing. It is a thing opening.</em>
          <span lang="ko">
            향기는 사물이 아닙니다. 피어나는 하나의 일입니다.
          </span>
        </p>
        <a className="bloom-hero__cta" href="#bloom-the-bloom">
          꽃이 피는 자리로 <span aria-hidden="true">·</span> go to where it opens
        </a>
      </div>

      <p className="bloom-hero__hint">
        <span lang="ko">천천히 스크롤하세요</span> — every line draws as you go
      </p>
    </header>
  );
}

"use client";

import type { CSSProperties } from "react";
import { NOTES } from "./botanical";
import { useLineDraw } from "../hooks/useLineDraw";
import { usePrefersReducedMotion } from "../hooks/usePrefersReducedMotion";
import { useWashSettle } from "../hooks/useWashSettle";

/**
 * 둘 · The scent notes. Three botanical plates — top, heart, base — each
 * a small perfumer's illustration that draws itself stroke-by-stroke on
 * reveal (svg-line-draw), with its watercolor wash blooming behind it
 * (feturbulence-texture). The three families read left-to-right as the
 * scent's architecture: the bright opening, the floral heart, the deep
 * root.
 *
 * Each plate has its own drawing clock (useLineDraw per card) so they
 * each draw independently as you scroll into them — they are not slaved
 * to the hero's clock. Without JS or reduced motion, each stands fully
 * drawn and settled.
 */
function NoteCard({
  note,
  index,
  reduced,
}: {
  note: (typeof NOTES)[number];
  index: number;
  reduced: boolean;
}) {
  const drawRef = useLineDraw<HTMLDivElement>(reduced);
  const washRef = useWashSettle<HTMLDivElement>(reduced);
  const p = note.plate;

  return (
    <article
      className={`bloom-note bloom-note--${note.family}`}
      data-reveal=""
      style={{ "--i": index } as CSSProperties}
    >
      <div className="bloom-note__art">
        <div ref={drawRef} className="bloom-note__drawwrap">
          <div ref={washRef} className="bloom-note__washwrap">
            <svg
              className="bloom-wash-svg bloom-note__wash"
              viewBox={p.viewBox}
              preserveAspectRatio="xMidYMid meet"
              aria-hidden="true"
              focusable="false"
            >
              <defs>
                <filter
                  id={`bloom-note-${note.family}-wash`}
                  x="-25%"
                  y="-25%"
                  width="150%"
                  height="150%"
                >
                  <feTurbulence
                    type="fractalNoise"
                    baseFrequency={
                      note.family === "heart"
                        ? "0.014 0.02"
                        : note.family === "top"
                          ? "0.016 0.022"
                          : "0.01 0.016"
                    }
                    numOctaves="2"
                    seed={
                      note.family === "heart" ? 23 : note.family === "top" ? 41 : 59
                    }
                    result="wet"
                  />
                  <feDisplacementMap
                    in="SourceGraphic"
                    in2="wet"
                    scale="0"
                    xChannelSelector="R"
                    yChannelSelector="G"
                  />
                </filter>
              </defs>
              <g filter={`url(#bloom-note-${note.family}-wash)`}>
                {p.washes.map((w, i) => (
                  <path key={i} className={w.cls} d={w.d} />
                ))}
              </g>
            </svg>
          </div>
          <svg
            className="bloom-note__lines"
            viewBox={p.viewBox}
            preserveAspectRatio="xMidYMid meet"
            aria-hidden="true"
            focusable="false"
          >
            <g className="bloom-draw">
              {p.strokes.map((s, i) => (
                <path
                  key={`s${i}`}
                  className={`bloom-draw__stroke ${s.cls}`}
                  d={s.d}
                  pathLength={1}
                  strokeWidth={s.w}
                  style={
                    {
                      "--d0": s.d0,
                      "--d1": s.d1,
                    } as CSSProperties
                  }
                />
              ))}
            </g>
          </svg>
        </div>
      </div>
      <div className="bloom-note__label">
        <p className="bloom-note__family" aria-hidden="true">
          {String(index + 1).padStart(2, "0")}
        </p>
        <h3 className="bloom-note__name">
          <span lang="ko">{note.ko}</span>
          <span className="bloom-note__en">{note.en}</span>
        </h3>
        <p className="bloom-note__latin">{note.latin}</p>
        <p className="bloom-note__sense">
          {note.family === "top" && (
            <>
              <span lang="ko">처음 스치는 밝은 잎 — 귤꽃과 베르가못.</span>
              <em>The bright first leaf — neroli and bergamot.</em>
            </>
          )}
          {note.family === "heart" && (
            <>
              <span lang="ko">한가운데 피어오르는 작약 — 분홍빛 숨결.</span>
              <em>The peony that opens at the center — a pink breath.</em>
            </>
          )}
          {note.family === "base" && (
            <>
              <span lang="ko">마지막에 남는 뿌리 — 베티버와 이끼.</span>
              <em>The root that remains — vetiver and moss.</em>
            </>
          )}
        </p>
      </div>
    </article>
  );
}

